import Foundation
import ResoniqDiagnostics

/// Seat reports for the debug screens (`MeasureDebugScreens`) and the previews.
///
/// They are real `SeatReport`s: the Kit's own simulated listening room (`SimulatedRoom` in
/// `ResoniqDiagnosticsTests`) was recorded at three spots, run through `SpotAnalyzer` and `SeatDiagnosis`, and the
/// encoded reports are kept here with the numbers rounded to two decimals to keep the file small. The words,
/// findings and rows are exactly what the Kit made. The rooms:
///
/// - the mockup's: +9 dB at 41 Hz, -11 dB at 61 Hz, even above 100 Hz, left and right within about 1.2 dB, with a
///   room size whose modes sit on those two notes;
/// - an even room: nothing to find;
/// - two valid spots of the even room: not enough to conclude;
/// - the mockup's room heard through one speaker.
///
/// Regenerate them from `SeatBench` in `ResoniqDiagnosticsTests` if the Kit's report changes shape; a report that no
/// longer decodes is a loud failure in a debug build, not a silent one.
enum MeasureFixtures {
    /// The mockup's case: a boom and a missing note in the bass, the rest even, left matching right, and the room
    /// inferred from its size.
    static let mockup: SeatReport = decode(mockupJSON)

    /// Nothing outside the even band.
    static let even: SeatReport = decode(evenJSON)

    /// Two valid spots: the verdict says three are needed, and the running curve is drawn.
    static let inconclusive: SeatReport = decode(inconclusiveJSON)

    /// The mockup's room through one speaker: one trace, no left and right.
    static let single: SeatReport = decode(singleJSON)

    private static func decode(_ json: String) -> SeatReport {
        do {
            return try JSONDecoder().decode(SeatReport.self, from: Data(json.utf8))
        } catch {
            fatalError("A debug fixture no longer decodes as a SeatReport: \(error)")
        }
    }

